//! Tandem's global settings: iTerm2's user defaults that are not part of a profile.
//! One TOML file, only changed values written. Schema: schema/global.toml.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use toml::Value;

use crate::schema;

/// iTerm2's factory key map, pointer bindings, and key mapping presets
/// (schema/keymaps.toml, generated by scripts/gen-keymaps.py).
pub mod keymaps {
    use std::sync::OnceLock;

    fn file() -> &'static toml::Table {
        static FILE: OnceLock<toml::Table> = OnceLock::new();
        FILE.get_or_init(|| include_str!("../schema/keymaps.toml").parse().expect("schema/keymaps.toml must parse"))
    }

    fn section(name: &str) -> &'static toml::Table {
        file()[name].as_table().expect("keymaps.toml sections are tables")
    }

    pub fn factory_global() -> &'static toml::Table {
        section("global")
    }

    pub fn factory_pointer() -> &'static toml::Table {
        section("pointer")
    }

    /// The profile key mapping presets, by name.
    pub fn presets() -> &'static [(String, toml::Table)] {
        static LIST: OnceLock<Vec<(String, toml::Table)>> = OnceLock::new();
        LIST.get_or_init(|| {
            section("preset").iter().map(|(k, v)| (k.clone(), v.as_table().cloned().unwrap_or_default())).collect()
        })
    }
}

pub struct Globals {
    pub values: BTreeMap<String, Value>,
    path: PathBuf,
    /// "Custom Color Presets" as its write point read it (`color_presets::bound_custom`), shared
    /// by readers; replaced, never changed, so a reader can tell a new write by the pointer.
    custom_presets: std::sync::Arc<Vec<(String, crate::color_presets::Preset)>>,
}

#[derive(Serialize, Deserialize)]
struct FileFormat {
    #[serde(default)]
    settings: BTreeMap<String, Value>,
}

pub fn default_path() -> PathBuf {
    let base = std::env::var_os("APPDATA").map(PathBuf::from).unwrap_or_else(std::env::temp_dir);
    base.join("Tandem").join("settings.toml")
}

/// Keys whose presence means something even at the default: "AI Safety Check" chosen by the
/// person, on or off, ends its one-time question (`RemoteCommand+Mac.swift:36-38`,
/// `object(forKey:) != nil`); "SUEnableAutomaticChecks" present is Sparkle's "answered"
/// (`SUUpdater.m:199`).
const KEPT_WHEN_DEFAULT: [&str; 3] = [crate::ai_settings::SAFETY_CHECK, "NoSyncDisableDECRQCRA", crate::update::AUTOMATIC_KEY];

/// What iTerm2 reads for a key that is not set. The AI prompts' defaults live in their
/// resource files, not the schema.
fn default_of(key: &str) -> Option<Value> {
    match key {
        "GlobalKeyMap" => Some(Value::Table(keymaps::factory_global().clone())),
        "PointerActions" => Some(Value::Table(keymaps::factory_pointer().clone())),
        _ => match crate::ai_prompts::default_text(key) {
            Some(text) => Some(Value::String(text.to_string())),
            None => schema::find_global(key).and_then(|s| s.default.clone()),
        },
    }
}

impl Globals {
    /// All defaults, saved at `path`.
    pub fn empty(path: &Path) -> Globals {
        Globals { values: BTreeMap::new(), path: path.to_path_buf(), custom_presets: Default::default() }
    }

    pub fn load(path: &Path) -> Result<Globals, String> {
        let text = match std::fs::read_to_string(path) {
            Ok(t) => t,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Globals::empty(path)),
            Err(e) => return Err(format!("{}: {e}", path.display())),
        };
        let file: FileFormat = toml::from_str(&text).map_err(|e| format!("{}: {e}", path.display()))?;
        let mut g = Globals { values: file.settings, path: path.to_path_buf(), custom_presets: Default::default() };
        g.bound_values();
        Ok(g)
    }

    /// Applies the write-point bounds to values written in bulk (the file at load, a remote-prefs
    /// snapshot), as `set` does for one value.
    pub fn bound_values(&mut self) {
        match self.values.remove(crate::color_presets::CUSTOM_KEY) {
            Some(v) => self.set(crate::color_presets::CUSTOM_KEY, v),
            None => self.custom_presets = Default::default(),
        }
        // The WebView2 host's two text settings are bounded at the write too (13x B2).
        for key in crate::webhost::BOUNDED_KEYS {
            if let Some(v) = self.values.remove(key) {
                self.set(key, v);
            }
        }
    }

    /// The custom color presets, sanitized and bounded at the write (`color_presets::custom`).
    pub fn custom_presets(&self) -> &[(String, crate::color_presets::Preset)] {
        &self.custom_presets
    }

    /// The same list, shared: it is replaced on every write of the key.
    pub fn custom_presets_shared(&self) -> &std::sync::Arc<Vec<(String, crate::color_presets::Preset)>> {
        &self.custom_presets
    }

    pub fn save(&self) -> Result<(), String> {
        let text = toml::to_string(&FileFormat { settings: self.values.clone() }).map_err(|e| format!("saving settings: {e}"))?;
        if let Some(dir) = self.path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        }
        // Write a new file, then rename it over the old one, so a crash never leaves half a file.
        let tmp = self.path.with_extension("toml.tmp");
        std::fs::write(&tmp, text).map_err(|e| format!("{}: {e}", tmp.display()))?;
        std::fs::rename(&tmp, &self.path).map_err(|e| format!("{}: {e}", self.path.display()))
    }

    /// The stored value only, with no default: for a key whose presence means something
    /// (`KEPT_WHEN_DEFAULT`), as Sparkle reads `SUEnableAutomaticChecks`.
    pub fn raw(&self, key: &str) -> Option<&Value> {
        self.values.get(key)
    }

    /// The stored value, else iTerm2's default.
    pub fn get(&self, key: &str) -> Option<Value> {
        self.values.get(key).cloned().or_else(|| default_of(key))
    }

    /// Stores a value. A value equal to the default is removed, so the file keeps only changes,
    /// except for a key whose having been set at all is read (`KEPT_WHEN_DEFAULT`).
    pub fn set(&mut self, key: &str, value: Value) {
        // Custom color presets are bounded and sanitized here, whatever wrote them (B3).
        let value = if key == crate::color_presets::CUSTOM_KEY {
            let (value, list) = crate::color_presets::bound_custom(&value);
            self.custom_presets = std::sync::Arc::new(list);
            value
        } else {
            value
        };
        // The fixed-runtime hint and the user agent are bounded at the one write point (13x B2).
        let value = crate::webhost::bound_global(key, value);
        // A changed cookie setting is no longer the one the Claude Code setup turned on, so its
        // marker goes; the setup writes the marker after the setting (Task 8 fix round 2).
        if key == crate::api_profile::SET_COOKIE && value.as_bool() != Some(self.bool(key)) {
            self.values.remove(crate::claude_code::COOKIE_BY_KEY);
        }
        if default_of(key).as_ref() == Some(&value) && !KEPT_WHEN_DEFAULT.contains(&key) {
            self.values.remove(key);
        } else {
            self.values.insert(key.to_string(), value);
        }
    }

    /// An optional bool (`Setting::optional_bool`): the stored value, or None when the key
    /// was never set (the schema has no default to fall back on).
    pub fn optional_bool(&self, key: &str) -> Option<bool> {
        self.values.get(key).and_then(Value::as_bool)
    }

    /// Removes a stored value, so the file drops the key (an optional bool's Unspecified).
    pub fn unset(&mut self, key: &str) {
        self.values.remove(key);
        if key == crate::color_presets::CUSTOM_KEY {
            self.custom_presets = Default::default();
        }
    }

    /// A number stored as a float or an integer, else iTerm2's default; None when neither
    /// the file nor the schema has one (an undeclared key read with its own default).
    pub fn number(&self, key: &str) -> Option<f64> {
        self.get(key).and_then(|v| v.as_float().or_else(|| v.as_integer().map(|i| i as f64)))
    }

    pub fn bool(&self, key: &str) -> bool {
        self.get(key).and_then(|v| v.as_bool()).unwrap_or(false)
    }

    pub fn int(&self, key: &str) -> i64 {
        self.get(key).and_then(|v| v.as_integer()).unwrap_or(0)
    }

    pub fn string(&self, key: &str) -> String {
        self.get(key).and_then(|v| v.as_str().map(str::to_string)).unwrap_or_default()
    }

    pub fn table(&self, key: &str) -> toml::Table {
        self.get(key).and_then(|v| v.as_table().cloned()).unwrap_or_default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;
    use toml::Value;

    fn scratch(name: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("tandem-globals-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir.join("settings.toml")
    }

    #[test]
    fn defaults_come_from_iterm2() {
        let g = Globals::empty(&scratch("defaults"));
        assert_eq!(g.int("SwitchTabModifier"), 4);
        assert_eq!(g.int("SwitchWindowModifier"), 6);
        assert!(g.bool("RemapModifiersGlobally") && g.bool("ReportHorizontalScrollEvents"));
        assert_eq!(g.table("GlobalKeyMap")["0x9-0x40000"]["Action"].as_integer(), Some(32));
        assert_eq!(g.table("PointerActions")["Button,2,1,,"]["Action"].as_str(), Some("kPasteFromClipboardPointerAction"));
    }

    #[test]
    fn saves_only_changes_and_round_trips() {
        let path = scratch("round");
        let mut g = Globals::empty(&path);
        g.set("FocusFollowsMouse", Value::Boolean(true));
        g.set("SwitchTabModifier", Value::Integer(4));
        g.save().unwrap();
        let text = std::fs::read_to_string(&path).unwrap();
        assert!(text.contains("FocusFollowsMouse") && !text.contains("SwitchTabModifier"), "{text}");
        assert!(Globals::load(&path).unwrap().bool("FocusFollowsMouse"));
    }

    #[test]
    fn a_missing_file_is_all_defaults() {
        assert!(!Globals::load(&scratch("missing")).unwrap().bool("FocusFollowsMouse"));
    }

    #[test]
    fn a_corrupt_file_is_an_error_not_a_reset() {
        let path = scratch("corrupt");
        std::fs::write(&path, "not = [toml").unwrap();
        assert!(Globals::load(&path).is_err());
    }

    #[test]
    fn presets_are_the_three_iterm2_ships() {
        let names: Vec<&str> = keymaps::presets().iter().map(|(n, _)| n.as_str()).collect();
        assert_eq!(names, ["Natural Text Editing", "Simulate Numlock", "Terminal.app Compatibility"]);
        assert_eq!(keymaps::presets()[0].1.len(), 8);
    }

    #[test]
    fn optional_bools_follow_iterm2() {
        let prevent = crate::schema::find_global("PreventEscapeSequenceFromChangingProfile").unwrap();
        assert!(prevent.optional_bool());
        assert_eq!(prevent.default, None);
        assert!(!crate::schema::find_global("NoSyncDisableOpenURL").unwrap().optional_bool());
        let path = scratch("optional");
        let mut g = Globals::empty(&path);
        assert_eq!(g.optional_bool("PreventEscapeSequenceFromChangingProfile"), None);
        // A stored No is not the default (there is none), so the file keeps it.
        g.set("PreventEscapeSequenceFromChangingProfile", Value::Boolean(false));
        assert_eq!(g.optional_bool("PreventEscapeSequenceFromChangingProfile"), Some(false));
        g.save().unwrap();
        assert!(std::fs::read_to_string(&path).unwrap().contains("PreventEscapeSequenceFromChangingProfile"));
        // Unspecified removes the key.
        g.unset("PreventEscapeSequenceFromChangingProfile");
        assert_eq!(g.optional_bool("PreventEscapeSequenceFromChangingProfile"), None);
        g.save().unwrap();
        assert!(!std::fs::read_to_string(&path).unwrap().contains("PreventEscapeSequenceFromChangingProfile"));
        // Removing a key never set does nothing.
        g.unset("PreventEscapeSequenceFromChangingProfile");
        assert!(g.values.is_empty());
    }

    /// 13o Task 6 (B4): a "No" to the DECRQCRA question is "Disable DECRQCRA" true, the schema
    /// default; it must stay in the file or the question comes back every time.
    #[test]
    fn decrqcra_no_is_remembered() {
        let path = scratch("decrqcra");
        let mut g = Globals::empty(&path);
        assert_eq!(g.optional_bool("NoSyncDisableDECRQCRA"), None);
        g.set("NoSyncDisableDECRQCRA", Value::Boolean(true));
        g.save().unwrap();
        assert_eq!(Globals::load(&path).unwrap().optional_bool("NoSyncDisableDECRQCRA"), Some(true));
        let mut g = Globals::empty(&path);
        g.set("NoSyncDisableDECRQCRA", Value::Boolean(false));
        assert_eq!(g.optional_bool("NoSyncDisableDECRQCRA"), Some(false));
    }

    #[test]
    fn every_global_default_fits_its_kind() {
        for s in crate::schema::global() {
            assert!(crate::schema::default_fits(s), "{}", s.key);
        }
    }
}
